});

// zoominfoToken.js — pure token cache/refresh helpers for the ZoomInfo OAuth2 flow.
//
// ZoomInfo (Okta) issues short-lived bearer tokens. For AUTONOMOUS operation the
// workflow must mint its own token from long-lived client_id + client_secret and
// re-mint when it expires or is rejected (401) — never store a static token.
//
// These are PURE functions (no n8n, no network) so they unit-test against Node.
// In the local replica the Code node wraps them around $getWorkflowStaticData (cross-run
// cache), this.helpers.httpRequest, and Date.now(). In the n8n Cloud deploy (Phase 16
// split-code-node) the mint is done by a credential-bound "ZoomInfo Mint" HTTP node —
// these helpers run in the SECRET-FREE Token Gate/Cache Code nodes (cache + expiry +
// re-mint-on-401 decisioning only; no client_id/client_secret ever in a Code node).
//
// Cache shape stored in workflow static data: { access_token, exp, token_type }
//   exp = absolute expiry in epoch MILLISECONDS.

// Mint a new token iff there is no cached token or it is within `skewMs` of expiry.
// Minting slightly early (default 60s skew) avoids using a token that dies mid-request.
function needsMint(cached, nowMs, skewMs = 60000) {
  if (!cached || !cached.access_token || !cached.exp) return true;
  return cached.exp - nowMs <= skewMs;
}

// Absolute expiry (epoch ms) from the token response's `expires_in` (seconds).
// Missing/invalid expires_in -> conservative 5-minute lifetime so we re-mint soon
// rather than trust an unknown-lifetime token indefinitely.
function computeExpiry(expiresInSec, nowMs) {
  const secs = Number(expiresInSec);
  if (!Number.isFinite(secs) || secs <= 0) return nowMs + 5 * 60000;
  return nowMs + secs * 1000;
}

// Parse an OAuth token-endpoint response into the cache shape. Accepts the JSON
// object or a raw JSON string. Throws if no token field is present (fail loud —
// a tokenless response must not be cached as if valid).
function parseTokenResponse(body, nowMs) {
  const b = typeof body === "string" ? JSON.parse(body) : (body || {});
  const token = b.access_token || b.jwt || b.token;
  if (!token) throw new Error("ZoomInfo token response missing access_token");
  return {
    access_token: token,
    exp: computeExpiry(b.expires_in, nowMs),
    token_type: b.token_type || "Bearer",
  };
}

// A 401 means the token was rejected (expired/revoked) -> clear cache, re-mint, retry once.
// Other statuses (400/403/404/429/5xx) are NOT auth failures and must not trigger a re-mint.
function isAuthError(statusCode) {
  return Number(statusCode) === 401;
}

// Bug B (live 2026-07-28): n8n's this.helpers.httpRequest throws an AxiosError, whose
// status lives at `e.response.status` — a shape the original inline check
// (statusCode/httpCode/response.statusCode) never covered, so a real 401 was silently
// missed and the cache never cleared. Tries every shape actually observed in this
// runtime (axios; n8n's NodeApiError, whose httpCode is sometimes a STRING; a bare
// statusCode) and, as a last resort, parses the "status code NNN" trailer n8n/axios
// append to the error message. Returns NaN (never a false 401) when nothing usable is
// found — isAuthError(NaN) is false, matching the safe conservative default.
function extractErrorStatus(e) {
  if (!e) return NaN;
  const candidates = [
    e.statusCode,
    e.httpCode,
    e.response && e.response.status,
    e.response && e.response.statusCode,
  ];
  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== "") {
      const n = Number(c);
      if (Number.isFinite(n)) return n;
    }
  }
  const m = /status code (\d{3})/i.exec((e && e.message) || "");
  return m ? Number(m[1]) : NaN;
}
// n8n Code node: cached ZoomInfo bearer (autonomous). Reads a cross-run token cache
// from workflow static data, mints only when missing/near-expiry, enriches with the
// Bearer, and on a 401 clears the cache, re-mints ONCE, and retries. Secrets come from
// n8n Variables ($vars.ZOOMINFO_CLIENT_ID / $vars.ZOOMINFO_CLIENT_SECRET) so no static
// token is ever stored. (Self-hosted may use $env; or bind a Basic Auth credential to a
// dedicated mint HTTP node instead.)
const TOKEN_URL = "https://api.zoominfo.com/gtm/oauth/v1/token";
const ENRICH_URL = "https://api.zoominfo.com/gtm/data/v1/companies/enrich";
const sd = $getWorkflowStaticData("global");

async function mint() {
  // Cloud: n8n Variables ($vars). Self-hosted/headless: process env ($env). Prefer $vars.
  const cid = ($vars && $vars.ZOOMINFO_CLIENT_ID) || $env.ZOOMINFO_CLIENT_ID;
  const csec = ($vars && $vars.ZOOMINFO_CLIENT_SECRET) || $env.ZOOMINFO_CLIENT_SECRET;
  const basic = Buffer.from(cid + ":" + csec).toString("base64");
  const resp = await this.helpers.httpRequest({
    method: "POST", url: TOKEN_URL,
    headers: { Authorization: "Basic " + basic, "Content-Type": "application/x-www-form-urlencoded" },
    body: "grant_type=client_credentials",
  });
  const parsed = parseTokenResponse(resp, Date.now());
  sd.zoominfo = parsed;              // cache across executions
  return parsed.access_token;
}

async function getToken() {
  if (needsMint(sd.zoominfo, Date.now())) return await mint.call(this);
  return sd.zoominfo.access_token;
}

async function enrich(token, payload) {
  // GTM data API is JSON:API — content-type/accept MUST be application/vnd.api+json.
  return await this.helpers.httpRequest({
    method: "POST", url: ENRICH_URL,
    headers: { Authorization: "Bearer " + token,
               "Content-Type": "application/vnd.api+json", Accept: "application/vnd.api+json" },
    body: JSON.stringify(payload || {}),
  });
}

// Companies enrich contract (LIVE-confirmed 200 against racingnsw.com.au):
//   { data: { type: "CompanyEnrich", attributes: { matchCompanyInput:[{companyWebsite|companyName}],
//     outputFields:[...] } } }
// Response: { data:[{ id, type:"Company"|"NoMatch", attributes:{...}, meta:{matchStatus} }] }.
//
// Every outputField below returned 200 when probed individually. `companyType` is NOT
// valid/entitled (400 PFAPI0009) — do not re-add it without re-probing.
//
// UNITS WARNING: `revenue` is in THOUSANDS. `revenueRange` ("$250 mil. - $500 mil.") is
// requested alongside it because normalizeProviders prefers the unambiguous string.
const ZOOM_CO_OUTPUT_FIELDS = [
  "id", "name", "website", "revenue", "revenueRange", "employeeCount", "employeeRange",
  "country", "primaryIndustry", "naicsCodes", "descriptionList", "foundedYear",
];
function toMatchCompanyInput(id) {
  const m = {};
  if (id && id.domain) m.companyWebsite = id.domain;
  if (id && id.companyName) m.companyName = id.companyName;
  return m;
}
// A domain OR a company name is enough; a keyless matchCompanyInput is itself a 400.
function hasZoomCoKey(m) { return !!(m.companyWebsite || m.companyName); }

// identity_keys lives on the Company Gate rows; $input here is the Apollo Org HTTP
// response (which has replaced $json), so pull identity by paired index from the Gate.
const gateRows = (function () { try { return $('Company Gate').all(); } catch (e) { return []; } })();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const id = (gateRows[i] && gateRows[i].json && gateRows[i].json.identity_keys) || item.json.identity_keys || {};
  const co = toMatchCompanyInput(id);
  const payload = hasZoomCoKey(co)
    ? { data: { type: "CompanyEnrich", attributes: { matchCompanyInput: [co], outputFields: ZOOM_CO_OUTPUT_FIELDS } } }
    : null;
  if (!payload) { out.push({ json: { skipped: "no zoominfo company match key" } }); continue; }
  let token = await getToken.call(this);
  let res;
  try {
    res = await enrich.call(this, token, payload);
  } catch (e) {
    if (isAuthError(extractErrorStatus(e))) {
      delete sd.zoominfo;                     // token rejected -> re-mint once + retry
      token = await mint.call(this);
      try { res = await enrich.call(this, token, payload); }
      catch (e2) { res = { error: String((e2 && e2.message) || e2) }; }
    } else {
      res = { error: String((e && e.message) || e) };  // non-auth error -> continue
    }
  }
  out.push({ json: res });
}
return out;

// normalizePhone.js — pure-JS AU phone normalizer for n8n Code nodes.
//
// DISCLAIMER: This is an AU-ONLY heuristic, NOT libphonenumber. It cannot import
// npm (n8n Code nodes run pure JS with no requires), so it recognises only the AU
// formats the ingestion pipeline actually sees. Any number that is non-AU or
// ambiguous returns null — the caller must route null to review, never silently
// drop or guess. A leading '+' is trusted as already-E.164 and passed through
// (separators stripped) WITHOUT a validity check, so an invalid '+...' string is
// kept as-is here where the Python oracle (phonenumbers.is_valid_number) would
// reject it. Swap this for a phone-validation API for global fidelity later.
//
// Mirrors src/normalizer.py normalize_phone for the AU cases the parity test pins.

function normalizePhoneAU(raw) {
  if (raw === null || raw === undefined || raw === "") return null;
  // Strip spaces, dashes, parens, dots — everything that is pure separator.
  const s = String(raw).replace(/[\s\-().]/g, "");
  if (s === "") return null;

  // Already international: trust the '+', keep the digits after it.
  if (s.startsWith("+")) {
    const digits = s.slice(1);
    if (!/^\d+$/.test(digits)) return null; // "+garbage" -> review
    return "+" + digits;
  }

  if (!/^\d+$/.test(s)) return null; // any non-digit leftover -> not AU/ambiguous

  // 0XXXXXXXXX — 10-digit AU national (mobile 04.. or landline 0[2378]..).
  if (s.length === 10 && s[0] === "0") {
    return "+61" + s.slice(1);
  }

  // 61XXXXXXXXX — AU country code without the '+'.
  if (s.length === 11 && s.startsWith("61")) {
    return "+" + s;
  }

  return null; // anything else is non-AU or ambiguous -> review
}

// normalizePhone(raw, region) — region-aware E.164 normalizer.
//
// Still NOT libphonenumber (n8n Code nodes can't require npm), but deterministic and
// keyed off the ISO2 country the PROVIDERS already return (Lusha location.country_iso2,
// Apollo person country, etc.) instead of guessing. Rules, in order:
//   1. Already `+E.164` -> trust and keep (digits 6-15).
//   2. Known region -> prepend that country's calling code (stripping a trunk 0 for
//      AU/NZ/GB/IE, a leading 1 for US/CA), gated by a per-country NSN-length sanity check.
//   3. Unknown/absent region -> fall back to normalizePhoneAU (AU heuristic). A non-AU
//      national number then returns null -> the caller drops it (never a bad write).
// The NSN-length gate is a sanity filter, not full validation; swap for a phone API when
// global precision matters (same external-call pattern as the email verifier).
const CALLING_CODE = { AU: "61", NZ: "64", US: "1", CA: "1", GB: "44", IE: "353", IN: "91", SG: "65" };
const NSN_LEN = { "61": [9], "64": [8, 9], "1": [10], "44": [9, 10], "353": [9], "91": [10], "65": [8] };
const TRUNK_REGIONS = /^(AU|NZ|GB|IE)$/;

function _nsnOk(cc, nsn) {
  const lens = NSN_LEN[cc];
  return lens ? lens.includes(nsn.length) : (nsn.length >= 6 && nsn.length <= 14);
}

function normalizePhone(raw, region) {
  if (raw === null || raw === undefined || raw === "") return null;
  const s = String(raw).replace(/[\s\-().]/g, "");
  if (s === "") return null;
  if (s.startsWith("+")) {
    const d = s.slice(1);
    return /^\d{6,15}$/.test(d) ? "+" + d : null;
  }
  if (!/^\d+$/.test(s)) return null;
  const r = String(region || "").toUpperCase();
  const cc = CALLING_CODE[r];
  if (!cc) return normalizePhoneAU(s); // unknown region -> AU heuristic (non-AU -> null)
  if (s.startsWith(cc) && _nsnOk(cc, s.slice(cc.length))) return "+" + s; // already has CC
  let nsn = s;
  if (TRUNK_REGIONS.test(r) && nsn.startsWith("0")) nsn = nsn.slice(1);          // trunk 0
  if (cc === "1" && nsn.length === 11 && nsn.startsWith("1")) nsn = nsn.slice(1); // US/CA leading 1
  return _nsnOk(cc, nsn) ? "+" + cc + nsn : null;
}

// normalizeEmail.js — pure-JS email normalization for n8n Code nodes.
//
// normalizeEmailBasic does a BASIC syntactic check + trim/lowercase only. The
// authoritative validation is the external rapid-email-verifier API downstream;
// applyEmailVerification maps that verifier's response onto the row. This mirrors
// src/normalizer.py normalize_email closely enough for identity/dedupe parity:
// obviously-malformed -> null, otherwise trimmed+lowercased.

function normalizeEmailBasic(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim().toLowerCase();
  if (s === "") return null;
  // Basic shape: local@domain.tld, no spaces, one @, a dotted domain.
  // Deliberately conservative — the verifier API is the real authority.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return null;
  return s;
}

// Map a rapid-email-verifier result onto the row. `verifierResult` shape:
//   { status: "VALID"|"PROBABLY_VALID"|"INVALID_FORMAT"|"INVALID_DOMAIN"|"DISPOSABLE",
//     aliasOf?: "canonical@example.com" }
// Returns the fields to merge onto the row.
function applyEmailVerification(row, verifierResult) {
  const status = (verifierResult && verifierResult.status) || "INVALID_FORMAT";
  const alias = verifierResult && verifierResult.aliasOf;
  const raw = row ? row.email : undefined;

  // aliasOf is the canonical address when the verifier resolved one.
  const canonical = alias
    ? normalizeEmailBasic(alias)
    : normalizeEmailBasic(raw);

  const valid = status === "VALID" || status === "PROBABLY_VALID";

  return {
    email_normalized: valid ? canonical : normalizeEmailBasic(raw),
    email_valid: valid,
    email_status: status,
    needs_review_reason: valid ? null : `email verifier: ${status}`,
  };
}

// normalizeProviders.js — pure-JS provider-response → common candidate shape.
//
// toCandidates(providerName, rawResponse, objectType) flattens ONE provider's raw
// API response into an array of common-shape candidates, one per usable field:
//   { field, source, value, normalizedValue, accuracy, recencyDate }
// where `field` is the canonical HubSpot property, `value` is the raw provider
// value, `normalizedValue` is the cross-check key (E.164 phone / lowercased email /
// revenue band / employee band / NAICS code), `accuracy` (0-1) is derived from the
// provider's per-field quality signal (see ENRICHMENT-WORKFLOW-PLAN.md §2 A-table),
// and `recencyDate` is the field's freshness date for the recency term.
//
// NO npm. Reuses normalizePhoneAU / normalizeEmailBasic from siblings. Revenue and
// employee band normalizers are local (mirror src/normalizer.py) — small enough to
// keep here rather than import a fourth module.


// Country NAME -> ISO2 (Apollo returns names like "United States"; Lusha gives country_iso2
// directly). Unmapped -> undefined, so normalizePhone falls back to its AU heuristic.
const _COUNTRY_ISO2 = {
  australia: "AU", "new zealand": "NZ", "united states": "US", "united states of america": "US",
  canada: "CA", "united kingdom": "GB", "great britain": "GB", england: "GB", ireland: "IE",
  india: "IN", singapore: "SG",
};
function _iso2(nameOrCode) {
  if (!nameOrCode) return undefined;
  const v = String(nameOrCode).trim();
  if (/^[A-Za-z]{2}$/.test(v)) return v.toUpperCase();  // already ISO2
  return _COUNTRY_ISO2[v.toLowerCase()];
}

// ---- local value normalizers (mirror src/normalizer.py band logic) ----------
// Parse a revenue value (number OR range string like "10M-25M") to lower-bound
// dollars, then map to the CLAUDE.md revenue bands. Range strings use the LOWER
// bound so "10M-25M" -> 5-50M, "50M-100M" -> 50-500M.
function _revenueToDollars(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return value;
  const s = String(value);
  const m = s.match(/([\d.]+)\s*([kmb]?)/i); // first magnitude
  if (!m) return null;
  let n = parseFloat(m[1]);
  if (Number.isNaN(n)) return null;
  const unit = (m[2] || "").toLowerCase();
  if (unit === "k") n *= 1e3;
  else if (unit === "m") n *= 1e6;
  else if (unit === "b") n *= 1e9;
  return n;
}

function normalizeRevenueBand(value) {
  const v = _revenueToDollars(value);
  if (v === null) return null;
  if (v < 1e6) return "<1M";
  if (v < 5e6) return "1-5M";
  if (v < 50e6) return "5-50M";
  if (v < 500e6) return "50-500M";
  if (v < 750e6) return "500-750M";
  if (v < 1e9) return "750M-1B";
  if (v < 1.2e9) return "1B-1.2B";
  return "1.2B+";
}

function normalizeEmployeeBand(value) {
  if (value === null || value === undefined || value === "") return null;
  // Already a band string (e.g. ZoomInfo employeeRange "201-500") -> pass through, with
  // whitespace around the hyphen collapsed: live Lusha returns "51 - 200", and the spaced
  // form is NOT an lv_employee_band enum value ("51-200" is).
  if (typeof value === "string" && !/^\d+$/.test(value.trim())) {
    return value.trim().replace(/\s*-\s*/g, "-");
  }
  const v = parseInt(value, 10);
  if (Number.isNaN(v)) return null;
  if (v <= 9) return "1-9";
  if (v <= 50) return "10-50";
  if (v <= 200) return "51-200";
  if (v <= 500) return "201-500";
  if (v <= 1000) return "501-1000";
  return "1001+";
}

function normalizeCountryRegion(value) {
  if (!value) return null;
  const v = String(value).trim().toLowerCase();
  if (["australia", "au", "aus"].includes(v)) return "AU";
  if (["new zealand", "nz"].includes(v)) return "NZ";
  return "Other";
}

function _clamp01(n) {
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}

// ---- per-provider accuracy helpers (ENRICHMENT-WORKFLOW-PLAN.md §2) ---------
const APOLLO_EMAIL_A = { verified: 1.0, guessed: null, pending: 0.3, unavailable: 0, bounced: 0 };

function apolloEmailAccuracy(raw) {
  const status = raw.email_status;
  let a;
  if (status === "guessed") {
    // guessed = 0.5 * extrapolated_confidence (default confidence 1.0 when absent).
    let ex = raw.extrapolated_email_confidence;
    if (ex === null || ex === undefined) ex = 1.0;
    if (ex > 1) ex = ex / 100; // tolerate 0-100 scale
    a = 0.5 * ex;
  } else {
    a = APOLLO_EMAIL_A[status];
    if (a === null || a === undefined) a = 0; // unknown status -> no trust
  }
  if (raw.email_domain_catchall) a *= 0.6; // catchall penalty
  return _clamp01(a);
}

const LUSHA_EMAIL_CONF = { "A+": 1.0, A: 0.8 };
function lushaEmailAccuracy(e) {
  // Live v2 email item uses emailConfidence/emailType; flat fixtures use confidence/type.
  const conf = e.confidence != null ? e.confidence : e.emailConfidence;
  const type = e.type != null ? e.type : e.emailType;
  let a = LUSHA_EMAIL_CONF[conf];
  if (a === null || a === undefined) a = 0.4; // null/unknown grade
  if (type && String(type).toLowerCase() !== "work") a *= 0.8; // private/personal
  return _clamp01(a);
}

// ---- provider mappers -------------------------------------------------------
function _push(out, field, source, value, normalizedValue, accuracy, recencyDate) {
  if (value === null || value === undefined || value === "") return;
  out.push({ field, source, value, normalizedValue, accuracy: _clamp01(accuracy), recencyDate: recencyDate || null });
}

function lushaCandidates(rawResponse, objectType) {
  const out = [];
  const src = "lusha";
  // Live v2/person response (confirmed 2026-07-28 against portal 22617666) is a
  // PLURAL, contactId-keyed map: {"contacts": {"<contactId>": {error, isCreditCharged,
  // data: {...}}}}. A per-contact `error` or a missing `data` key must never throw
  // (skip-not-retry, CLAUDE.md Sec 26.1) -- both fall through to {} (zero candidates
  // for this row). The singular `contact.data` form below was never actually observed
  // live -- it is kept only for the pre-existing offline fixture/back-compat shape.
  let raw = rawResponse || {};
  if (raw.contacts && typeof raw.contacts === "object") {
    const entry = Object.values(raw.contacts)[0];
    raw = (entry && !entry.error && entry.data) || {};
  } else if (raw.contact && raw.contact.data) {
    raw = raw.contact.data;
  }
  const updated = raw.updateDate;
  const region = raw.location && (raw.location.country_iso2 || raw.location.country); // ISO2 or name
  if (objectType === "contacts") {
    // Live: emailAddresses/phoneNumbers with emailType/phoneType; fixtures: emails/phones with type.
    for (const e of raw.emailAddresses || raw.emails || []) {
      _push(out, "email", src, e.email, normalizeEmailBasic(e.email), lushaEmailAccuracy(e), e.updateDate || updated);
    }
    for (const p of raw.phoneNumbers || raw.phones || []) {
      if (p.doNotCall) continue; // suppress (not just downscore) per §2
      const norm = normalizePhone(p.number, _iso2(region));
      if (!norm) continue; // null-drop: un-normalizable phone never reaches HubSpot
      const t = String(p.phoneType || p.type || "").toLowerCase();
      const acc = t === "mobile" || t === "direct" ? 0.8 : 0.5;
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.number, norm, acc, p.updateDate || updated);
    }
    if (raw.jobTitle) {
      // No per-field grade for Lusha title -> ungraded base 0.6.
      _push(out, "jobtitle", src, raw.jobTitle.title, _norm(raw.jobTitle.title), 0.6, updated);
      _push(out, "seniority", src, raw.jobTitle.seniority, _norm(raw.jobTitle.seniority), 0.6, updated);
    }
  } else {
    // company firmographics — no per-field grade -> base 0.6. Live nests under `company`
    // with array revenueRange/companySize [lo,hi] and location.countryIso2; fixtures are flat.
    // Live /v2/company wraps the record in `data`; the person endpoint uses `company`;
    // fixtures are flat. Without the `data` unwrap the live company response yielded
    // ZERO candidates (every lookup hit the envelope, not the record).
    const co = raw.company || raw.data || raw;
    const rev = Array.isArray(co.revenueRange) ? co.revenueRange[0] : co.revenueRange;
    _push(out, "lv_revenue_band", src, rev, normalizeRevenueBand(rev), 0.6, updated);
    // Live /v2/company returns the headcount as `employees` ("51 - 200", a spaced range
    // string); companySize/employeeCount are null there and only appear in the fixtures.
    const emp = Array.isArray(co.companySize)
      ? co.companySize[co.companySize.length - 1]
      : (co.companySize != null ? co.companySize
        : (co.employeeCount != null ? co.employeeCount : co.employees));
    _push(out, "lv_employee_band", src, emp, normalizeEmployeeBand(emp), 0.6, updated);
    const naics = (co.naicsCodes || [])[0];
    _push(out, "industry", src, naics || co.mainIndustry, naics ? String(naics) : _norm(co.mainIndustry), 0.6, updated);
    const country = (co.location && co.location.countryIso2) || co.countryIso2;
    _push(out, "lv_country_region_normalized", src, country, normalizeCountryRegion(country), 0.6, updated);
  }
  return out;
}

function apolloCandidates(raw, objectType) {
  const out = [];
  const src = "apollo";
  // Live people/match nests the record under `person`; flat fixtures don't. Read
  // through `person` so both shapes work (mirrors the org fallback below).
  const person = raw.person || raw;
  const updated = person.updated_at || raw.updated_at;
  if (objectType === "contacts") {
    _push(out, "email", src, person.email, normalizeEmailBasic(person.email), apolloEmailAccuracy(person), updated);
    const region = _iso2(person.country || (person.organization && person.organization.country));
    for (const p of person.phone_numbers || []) {
      if (p.dnc_status || p.doNotCall) continue; // suppress
      const norm = normalizePhone(p.sanitized_number, region);
      if (!norm) continue; // null-drop: un-normalizable phone never reaches HubSpot
      const status = p.status || p.status_cd;
      const acc = status === "valid_number" ? 1.0 : 0.5;
      const t = String(p.type || "").toLowerCase();
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.sanitized_number, norm, acc, updated);
    }
    _push(out, "jobtitle", src, person.title, _norm(person.title), 0.6, updated);
    _push(out, "seniority", src, person.seniority, _norm(person.seniority), 0.6, updated);
  } else {
    const org = (raw.person && raw.person.organization) || raw.organization || raw.org || raw;
    // Live org revenue is `organization_revenue` (number); flat fixtures use `annual_revenue`.
    const revenue = org.annual_revenue != null ? org.annual_revenue : org.organization_revenue;
    _push(out, "lv_revenue_band", src, revenue, normalizeRevenueBand(revenue), 0.6, updated);
    _push(out, "lv_employee_band", src, org.estimated_num_employees, normalizeEmployeeBand(org.estimated_num_employees), 0.6, updated);
    // Apollo org industry is free-text (no NAICS in this contract) -> lowercase text key.
    _push(out, "industry", src, org.industry, _norm(org.industry), 0.6, updated);
  }
  return out;
}

// Unwrap the GTM enrich response envelope to a flat contact record.
// Live GTM (confirmed 200): { data: [ { attributes:{...fields}, meta:{matchStatus}, id } ] }
// (JSON:API). We flatten attributes and lift matchStatus/id up. Older/flat fixture
